  wh: {
    goal: "Kerakli ma'lumotni so'ray olasan: <i>Where do you live?</i>, <i>What's your name?</i>, <i>Why are you sad?</i> So'zlar tartibini adashtirmaysan.",
    story: { title: "Tanishuv", lines: [
      ["A", "*What*'s your name?", "Ismingiz nima?"],
      ["B", "I'm Gojo. *Where* are you from?", "Men Gojoman. Qayerdansiz?"],
      ["A", "I'm from Canada. *Where* do you live?", "Kanadadanman. Siz qayerda yashaysiz?"],
      ["B", "In Tashkent. *What* do you do?", "Toshkentda. Nima ish qilasiz?"],
      ["A", "I'm a teacher. *How* old are you?", "O'qituvchiman. Necha yoshdasiz?"],
      ["B", "I'm twenty. *Why* are you in Uzbekistan?", "Yigirmadaman. O'zbekistonda nima uchun yuribsiz?"],
    ]},
    notice: [
      { s: "Where do you live?", a: "Where", q: "Savol so'zini bos. U gapning qayerida turibdi?" },
      { s: "What do you do?", a: "do", q: "Savol so'zidan keyin kelgan yordamchi so'zni bos (birinchi do)." },
    ],
    parts: [
      { h: "1. Savol so'zlari", rows: [["*What*", "nima"], ["*Where*", "qayerda, qayerga"], ["*When*", "qachon"], ["*Why*", "nega, nima uchun"], ["*Who*", "kim"], ["*How*", "qanday"], ["*How old*", "necha yoshda"], ["*How much*", "qancha (narx)"]] },
      { h: "2. O'zbekchadan farqi", t: "O'zbekchada savol so'zi gapning o'rtasida bo'lishi mumkin: <i>Sen <b>qayerda</b> yashaysan?</i> Inglizchada esa savol so'zi <b>doim birinchi</b> turadi: <i><b>Where</b> do you live?</i>" },
      { h: "3. Ikki xil formula", rows: [["Savol so'zi + *am/is/are* + kim ... ?", "holat haqida"], ["Where *are* you?", "qayerdasan?"], ["Savol so'zi + *do/does* + kim + fe'l?", "ish haqida"], ["Where *do* you work?", "qayerda ishlaysan?"], ["What *does* she want?", "u nima istaydi?"]],
        n: "Fe'l bo'lmasa (holat, joy, yosh) → <b>am/is/are</b>. Oddiy fe'l bo'lsa (live, work, like) → <b>do/does</b>." },
      { h: "4. Ko'p uchraydigan xatolar", bad: [
        ["Where you live?", "Where do you live?", "Oddiy fe'lda do kerak."],
        ["What your name is?", "What is your name?", "is savol so'zidan keyin turadi."],
        ["Where does she works?", "Where does she work?", "does dan keyin toza fe'l."],
        ["How many it costs?", "How much does it cost?", "Narx → how much + does."],
      ]},
    ],
    ccq: [
      { q: "“Qachon?” inglizchada?", a: "When", o: ["Where", "What"], why: "when = qachon." },
      { q: "Qaysi biri to'g'ri?", a: "Where do you work?", o: ["Where you work?", "Where you do work?"], why: "Where + do + you + fe'l." },
      { q: "“Ismingiz nima?” uchun qaysi yordamchi so'z?", a: "is", o: ["do", "does"], why: "Fe'l yo'q, holat → is: What is your name?" },
    ],
    tasks: [
      { k: "fill", s: "___ do you live?", a: "Where", o: ["Where", "Who", "When"], uz: "Qayerda yashaysan?", why: "joy → where." },
      { k: "fill", s: "___ is your birthday?", a: "When", o: ["When", "Where", "Who"], uz: "Tug'ilgan kuning qachon?", why: "vaqt → when." },
      { k: "fill", s: "___ is that man?", a: "Who", o: ["Who", "What", "How"], uz: "Anavi odam kim?", why: "odam → who." },
      { k: "fill", s: "What ___ you do on weekends?", a: "do", o: ["do", "does", "are"], uz: "Dam olish kunlari nima qilasan?", why: "you + fe'l (do) → do." },
      { k: "fill", s: "Where ___ your parents?", a: "are", o: ["are", "do", "is"], uz: "Ota-onang qayerda?", why: "fe'l yo'q, they → are." },
      { k: "type", s: "___ are you sad?", h: "nega", a: "Why", uz: "Nega xafasan?", why: "sabab → why." },
      { k: "type", s: "How much ___ this bag cost?", h: "yordamchi (it)", a: "does", uz: "Bu sumka qancha turadi?", why: "it + cost → does." },
      { k: "spot", s: "What does your brother do?", a: "does", q: "Savol so'zidan keyingi yordamchi so'zni bos.", why: "What <b>does</b> your brother do?" },
      { k: "pick", title: "Qaysi gap to'g'ri?", q: "To'g'ri savolni tanla.", a: "How old is your sister?", o: ["How old your sister is?", "How old does your sister?"], why: "How old + is + kim?" },
      { k: "tr", uz: "Qayerda ishlaysan?", a: "Where do you work?", o: ["Where you work?", "You work where?"], why: "Where + do + you + work?" },
      { k: "order", en: "What time is it?", uz: "Soat necha bo'ldi?", why: "What time + is + it?" },
      { k: "listen", en: "Why do you learn English?", uz: "Nega ingliz tilini o'rganasan?", o: ["Qachondan beri ingliz tilini o'rganasan?", "Qayerda ingliz tilini o'rganasan?"] },
    ],
    say: [
      { en: "Where are you from?", uz: "Qayerdansiz?" },
      { en: "What do you do?", uz: "Nima ish qilasiz?" },
      { en: "How much is this?", uz: "Bu qancha turadi?" },
    ],
    final: [
      { k: "fill", s: "___ old are you?", a: "How", o: ["How", "What", "Who"], uz: "Necha yoshdasan?", why: "How old." },
      { k: "fill", s: "Where ___ she work?", a: "does", o: ["does", "do", "is"], uz: "U qayerda ishlaydi?", why: "she + fe'l → does." },
      { k: "type", s: "What ___ your phone number?", h: "...dir", a: "is", uz: "Telefon raqaming nima?", why: "fe'l yo'q → is." },
      { k: "type", s: "___ do you go to bed?", h: "qachon", a: "When", uz: "Qachon uxlaysan?", why: "vaqt → when." },
      { k: "tr", uz: "U nima istaydi?", a: "What does he want?", o: ["What he wants?", "What does he wants?"], why: "What + does + he + want?" },
      { k: "pick", s: "*Who* is your teacher?", q: "Bu savol nima haqida?", a: "Odam haqida", o: ["Joy haqida", "Vaqt haqida"], why: "who — kim." },
      { k: "order", en: "Where do your parents live?", uz: "Ota-onang qayerda yashaydi?", why: "Where + do + kim + fe'l?" },
      { k: "listen", en: "How are you today?", uz: "Bugun qandaysan?", o: ["Bugun qayerdasan?", "Kecha qanday o'tdi?"] },
    ],
  },

